S {"id": "Q01", "corrected_authoritative_source_references": [{"source": "M", "file": "/home/jonny/projects/boardgame-rules/docs/quality/summary-qa/dune-imperium-uprising/2026-11-04-batch-231507/dune-imperium-uprising-rules.txt", "kind": "text_lines", "lines": [190, 203], "pdf_pages": [4], "sha256": "b3ce948cce744b9b6ec8c4de16dbe76d8b393da9a5c7aa77d0d74d3f12aa229b"}]}
A {"id": "Q01", "answer": "Shuffle all 4 Conflict III cards and place them face down at the bottom; shuffle all 9 II cards and deal 5 face down above them; shuffle all 3 I cards and deal 1 face down on top. Return unused I and II cards to the box without looking at them.", "support": "supported", "evidence": "Setup: face-down 10-card Conflict Deck; shuffle each entire tier before dealing."}
