S {"id": "Q05", "corrected_authoritative_source_references": [{"source": "M", "file": "/home/jonny/projects/boardgame-rules/docs/quality/summary-qa/dune-imperium-uprising/2026-11-04-batch-231507/dune-imperium-uprising-rules.txt", "kind": "text_lines", "lines": [597, 620], "pdf_pages": [10], "sha256": "b3ce948cce744b9b6ec8c4de16dbe76d8b393da9a5c7aa77d0d74d3f12aa229b"}]}
A {"id": "Q05", "answer": "At a Combat space, you may deploy all 3 troops recruited this turn plus up to 2 from the garrison, for 5 total. At a non-Combat space you do not deploy troops. Recruited troops come from your supply into your garrison; if supply is empty you cannot recruit more.", "support": "supported", "evidence": "Recruiting & Deploying Units: newly recruited this turn plus up to two from garrison, at a Combat space; cube recruits from supply to garrison."}
